const ICONS={inbox:'M3 4h14l3 8v7H2v-7L5 4 M2 12h5l2 3h4l2-3h5',check:'M5 11l4 4L19 5',box:'M4 4h14v15H4z M7 10l3 3 5-6',upload:'M11 15V2 M6 7l5-5 5 5 M3 13v7h16v-7',export:'M12 3H4v17h14v-8 M10 12L20 2 M14 2h6v6',file:'M5 2h9l5 5v14H5z M14 2v6h5 M8 12h8 M8 16h6',search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M4 11h15 M14 6l5 5-5 5',back:'M16 11H4 M9 6l-5 5 5 5',close:'M5 5l12 12 M17 5L5 17',alert:'M11 7v5 M11 16h.01 M11 2a9 9 0 1 1 0 18 9 9 0 0 1 0-18',clock:'M11 2a9 9 0 1 1 0 18 9 9 0 0 1 0-18 M11 6v6l4 2',layers:'M2 7l9-5 9 5-9 5z M2 12l9 5 9-5 M2 17l9 5 9-5',refresh:'M19 8a8 8 0 1 0 0 8 M19 2v6h-6',mail:'M2 4h19v15H2z M2 4l10 8 9-8',download:'M11 2v12 M6 9l5 5 5-5 M3 16v5h16v-5',link:'M8 14l6-6 M7 8l3-3a4 4 0 0 1 6 6l-2 2 M13 16l-3 3a4 4 0 0 1-6-6l2-2'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[n]||ICONS.file}"/></svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.getElementById('app');let cases=makeCases(),selected='BK-2048',filter='needs',search='',issueFilter='all',selectedField='gross_weight_kg',staged=[],importErrors=[],demoStaged=false,progress=0,pairSelection={si:'',bl:''},progressTimer=null,lastReviewCase='',lastPairCase='';
try{const s=JSON.parse(localStorage.getItem('verity-demo-v1'));if(Array.isArray(s)&&s.length===cases.length)cases=s}catch{}
function save(){try{localStorage.setItem('verity-demo-v1',JSON.stringify(cases))}catch{}}
function getCase(id){return cases.find(c=>c.id===id)}
function counts(c){const f=Object.values(c.fields);return {match:f.filter(x=>x.comparison==='MATCH').length,diff:f.filter(x=>x.comparison==='MISMATCH').length,unresolved:f.filter(x=>x.comparison===null).length}}
function mode(c){if(c.category!=='BL_COMPARISON')return 'complete';if(c.processing)return 'processing';if(c.processingError||c.docIssue||c.pairIssue||counts(c).unresolved)return 'needs';if(Object.values(c.fields).some(f=>f.comparison==='MISMATCH'&&!f.verified))return 'needs';return 'complete'}
function finding(c){if(c.category!=='BL_COMPARISON')return 'No BL comparison';if(c.processing)return 'Checking extracted fields';if(c.processingError)return c.processingError==='service_timeout'?'Reading service timed out':'Unsupported file format';if(c.docIssue)return {missing_si:'SI attachment missing',missing_bl:'BL attachment missing',wrong_type:'Invoice supplied instead of BL'}[c.docIssue];if(c.pairIssue)return c.multiple?'Multiple shipments to organize':'Multiple SI versions';const n=counts(c);if(n.diff&&n.unresolved)return `${n.diff} difference · ${n.unresolved} missing value`;if(n.unresolved)return {unreadable:'Scan remains unreadable',number:'Number format unclear',port:'Port alias is not unique',entity:'Company identity unclear',extraction:'Extracted value needs correction',evidence:'Source location unavailable',port_conflict:'Port name and code conflict',alias_unknown:'Port is not in the reference table',validity:'Container count needs confirmation'}[c.type]||'Field needs confirmation';if(n.diff)return `${n.diff} ${n.diff===1?'difference':'differences'}${mode(c)==='complete'?' · reviewed':''}`;return '7 fields matched'}
function next(c){if(c.category!=='BL_COMPARISON')return 'View classification';if(c.processing)return 'View progress';if(c.processingError)return c.processingError==='unsupported_format'?'Upload a supported file':c.retries?'Review failed stage':'Retry failed stage';if(c.docIssue)return c.docIssue==='missing_si'?'Upload SI':'Upload correct BL';if(c.pairIssue)return 'Choose SI and BL';if(mode(c)==='complete')return 'View result';return {mixed:'Upload supporting file',unreadable:'Upload clearer file',number:'Choose number interpretation',port:'Specify the location',entity:'Confirm with evidence',extraction:'Correct extracted value',evidence:'Review the full document',port_conflict:'Confirm port from source',alias_unknown:'Provide location evidence',validity:'Request corrected information'}[c.type]||'Verify the difference'}
function color(c){if(c.processing)return 'blue';if(c.category!=='BL_COMPARISON')return '';if(c.processingError)return 'red';if(c.pairIssue||c.docIssue||counts(c).unresolved)return 'amber';return counts(c).diff?'red':'green'}
function category(c){return {BL_COMPARISON:'BL comparison',SI_REQUEST:'SI request',INVOICE_QUERY:'Invoice query',GENERAL:'General',SPAM:'Spam'}[c.category]}
function badge(text,cls=''){return `<span class="badge ${cls}">${esc(text)}</span>`}function status(text,cls=''){return `<span class="status ${cls}"><i class="dot"></i>${esc(text)}</span>`}
function button(label,action,cls='',attrs=''){return `<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`}
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),3300)}
function addHistory(c,title,detail){c.history.unshift({title,detail,at:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});save()}
function route(){return (location.hash.slice(1)||'inbox').split('/')}
function go(hash){if(location.hash==='#'+hash)render();else location.hash=hash}
function shell(content,name,active='inbox'){const needs=cases.filter(c=>mode(c)==='needs').length,done=cases.filter(c=>mode(c)==='complete').length;app.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#inbox" aria-label="Verity inbox"><span class="brand-mark">❯</span>Verity</a><nav class="nav" aria-label="Main navigation">${[['inbox','inbox','Inbox',needs],['completed','box','Completed',done],['import','upload','Import',''],['exports','export','Exports','']].map(([key,ic,label,count])=>`<a href="#${key}" ${key==='inbox'?'data-action="nav-inbox"':''} class="${active===key?'active':''}">${icon(ic)}${label}${count!==''?`<span class="count">${count}</span>`:''}</a>`).join('')}</nav><div class="side-bottom"><nav class="nav"><a href="#screens" class="${active==='screens'?'active':''}">${icon('layers')}Page guide</a></nav><div class="demo-note"><strong>Preset demo</strong><p>Example cases · saved on this device</p><button class="link" style="font-size:12px;margin-top:9px" data-action="reset">Reset examples</button></div></div></aside><main class="workspace"><header class="topbar"><div class="crumb"><a href="#inbox">Workspace</a><span>/</span><span>${esc(name)}</span></div><div class="top-right"><span>Preset data · no live processing</span><span class="avatar">MW</span></div></header>${content}</main></div>`}
function render(){const [page,id]=route();if(['review','pair','email','history'].includes(page)&&!getCase(id)){go('inbox');return}if(page==='inbox'||page==='completed'||page==='records')renderInbox(page);else if(page==='review')renderReview(getCase(id));else if(page==='pair')renderPair(getCase(id));else if(page==='email')renderEmail(getCase(id));else if(page==='history')renderHistory(getCase(id));else if(page==='import')renderImport();else if(page==='progress')renderProgress();else if(page==='exports')renderExports();else if(page==='screens')renderGuide();else renderInbox('inbox')}
function rows(list,exp=false){return list.map(c=>`<tr data-action="select" data-id="${c.id}" class="${selected===c.id?'selected':''}" tabindex="0" aria-label="Open ${c.id}"><td><strong>${c.id}</strong><span class="company">${esc(c.company)}</span></td><td>${status(category(c),c.category==='BL_COMPARISON'?'red':'')}</td><td><span class="${color(c)}">${esc(finding(c))}</span></td><td class="next">${esc(exp?exportBlock(c)||'Ready for preview':next(c))}</td><td>${icon('arrow')}</td></tr>`).join('')}
function renderInbox(page){if(page==='completed')filter='complete';const list=cases.filter(c=>(filter==='all'||mode(c)===filter)&&(!search||`${c.id} ${c.company} ${finding(c)}`.toLowerCase().includes(search.toLowerCase()))&&(issueFilter==='all'||(issueFilter==='differences'&&counts(c).diff>0&&c.category==='BL_COMPARISON')||(issueFilter==='missing'&&(c.docIssue||Object.values(c.fields).some(f=>f.kind==='MISSING')))||(issueFilter==='uncertain'&&Object.values(c.fields).some(f=>f.kind==='AMBIGUOUS'))||(issueFilter==='failures'&&c.processingError)));if(!list.some(c=>c.id===selected))selected=list[0]?.id||'';const c=getCase(selected);shell(`<div class="inbox-layout"><section class="page"><div class="page-head"><div><h1>${page==='completed'?'Completed':'Inbox'}</h1><p>${page==='completed'?'Finished reviews and classified emails.':'Document checks that need attention.'}</p></div><a class="btn primary" href="#import">${icon('upload')}Import files</a></div><div class="tabs" role="tablist" aria-label="Record status">${[['needs','Needs action'],['processing','Processing'],['complete','Completed'],['all','All']].map(([key,label])=>`<button class="tab ${filter===key?'active':''}" role="tab" aria-selected="${filter===key}" data-action="filter" data-filter="${key}">${label}<b>${key==='all'?cases.length:cases.filter(c=>mode(c)===key).length}</b></button>`).join('')}</div><div class="toolbar"><div class="search">${icon('search')}<input id="search" aria-label="Search cases" placeholder="Search by reference, company, or issue…" value="${esc(search)}"></div><select id="issue-filter" aria-label="Issue type">${[['all','All issue types'],['differences','Differences'],['missing','Missing information'],['uncertain','Unclear meaning'],['failures','Processing errors']].map(([v,t])=>`<option value="${v}" ${issueFilter===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="panel"><div class="table-wrap"><table class="case-table"><thead><tr><th>Case</th><th>Email intent</th><th>Finding</th><th>Next step</th><th></th></tr></thead><tbody>${rows(list)}</tbody></table></div>${!list.length?`<div class="empty">${icon('search')}<h2>No cases here</h2><p>Try another filter or search term.</p>${button('Clear filters','clear-filters')}</div>`:''}<div class="table-footer"><span>${list.length} ${list.length===1?'record':'records'}</span><span>Sample batch · 20 Sep 2026</span></div></div></section><aside class="detail">${c?detail(c):'<div class="empty">Select a record to see its details.</div>'}</aside></div>`,page==='completed'?'Completed':'Inbox',page)}
function detail(c){const n=counts(c);return `<div class="flex" style="align-items:flex-start;gap:13px">${icon('file')}<div><h2>${c.id}</h2><p class="caption" style="margin-top:5px">${esc(c.company)}</p><p class="small muted" style="margin-top:12px">Received 20 Sep 2026<br>Ref: ${c.booking}</p></div></div><div class="alert ${color(c)||''}">${icon(c.processing?'clock':'alert')}<div><strong>${c.category!=='BL_COMPARISON'?'Classification complete':c.processing?'Processing':c.processingError?'Processing error':mode(c)==='complete'?'Review complete':'Needs action'}</strong><small>${esc(finding(c))}</small></div></div>${c.category==='BL_COMPARISON'&&!c.docIssue&&!c.pairIssue&&!c.processingError&&!c.processing?`<div class="panel"><div class="panel-head"><h3>Key findings</h3></div><div class="panel-body mini-rows">${Object.entries(c.fields).filter(([k,f])=>f.comparison!=='MATCH').map(([k,f])=>`<div><span>${LABELS[k]}</span><span class="${f.comparison?'red':'amber'}">SI ${esc(f.si)}<br>BL ${esc(f.bl)}</span></div>`).join('')||`<div><span>All seven fields</span><span class="green">Matched</span></div>`}</div></div>`:''}<div><p class="mini-heading">Email intent</p>${status(category(c),c.category==='BL_COMPARISON'?'red':'')}<p class="caption" style="margin-top:7px">${c.category==='BL_COMPARISON'?'Compare Shipping Instructions with a draft Bill of Lading.':'Classified only. Seven-field comparison does not apply.'}</p><a href="#email/${c.id}" class="link" style="display:inline-block;margin-top:10px">View email & classification</a></div><div class="rule"></div><div><p class="mini-heading">Next step</p><p style="font-size:14px">${esc(next(c))}</p></div><div class="bottom"><a class="btn primary block" href="#${c.category!=='BL_COMPARISON'?'email':c.pairIssue?'pair':c.processing?'progress':'review'}${c.processing?'':'/'+c.id}">${icon('file')}${c.category!=='BL_COMPARISON'?'View email':c.pairIssue?'Choose documents':c.processing?'View progress':'Open review'}${icon('arrow')}</a><p class="footer-note">Example data for exploring the workflow.</p></div>`}
window.addEventListener('hashchange',render);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if(a==='select'){selected=b.dataset.id;render()}else if(a==='filter'){filter=b.dataset.filter;if(route()[0]==='completed')go('inbox');else render()}else if(a==='clear-filters'){search='';filter='all';issueFilter='all';render()}else if(a==='reset'){if(confirm('Reset all preset examples and local review decisions?')){cases=makeCases();save();selected='BK-2048';filter='needs';go('inbox');toast('Preset examples reset.')}}else handleAction(a,b)});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-action]')){e.preventDefault();e.target.click()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const p=e.target.selectionStart;search=e.target.value;render();const t=document.getElementById('search');t?.focus();t?.setSelectionRange(p,p)}});
document.addEventListener('change',e=>{if(e.target.id==='issue-filter'){issueFilter=e.target.value;render()}else handleChange(e)});
function caseHeader(c,tab='review'){return `<div class="page-head review-head"><div><div class="flex" style="margin-bottom:9px"><a href="#inbox" class="caption">← Inbox</a>${badge(category(c))}${badge('Version '+c.version)}</div><h1>${c.id} <span style="font-size:17px;font-weight:400;color:var(--muted);letter-spacing:0">/ ${esc(c.company)}</span></h1><div class="review-tabs">${[['review','Field review'],['email','Email & classification'],['pair','Documents'],['history','History']].map(([v,t])=>`<a class="${tab===v?'active':''}" href="#${v}/${c.id}">${t}</a>`).join('')}</div></div><a class="btn" href="#exports">${icon('export')}Results</a></div>`}
function summary(c){if(c.processingError||c.docIssue||c.pairIssue)return `<div class="summary-strip">${status(finding(c),color(c))}<span class="muted">Comparison is paused. Earlier findings are retained.</span></div>`;const n=counts(c);return `<div class="summary-strip">${status(n.diff+' '+(n.diff===1?'difference':'differences'),'red')}${status(n.unresolved+' unresolved','amber')}${status(n.match+' matched','green')}<span class="muted" style="margin-left:auto;font-size:12px">${mode(c)==='complete'?'Review complete':'Your input is needed'}</span></div>`}
function sourceDoc(c,side,key,full=false){const missing=c.docIssue===(side==='si'?'missing_si':'missing_bl')||c.docIssue==='wrong_type'&&side==='bl';if(missing)return `<div class="source"><div class="source-top">${icon('file')}<div>${side==='si'?'Shipping Instructions':'Bill of Lading'}<small>No valid ${side.toUpperCase()} attached</small></div></div><div class="empty">${icon('file')}<h2>${c.docIssue==='wrong_type'?'Wrong document type':'File missing'}</h2><p>${c.docIssue==='wrong_type'?'The supplied file is an invoice. A draft BL is required.':'There is no source to compare yet.'}</p></div></div>`;return `<div class="source"><div class="source-top">${icon('file')}<div>${side==='si'?'Shipping Instructions':'Bill of Lading'}<small>${side.toUpperCase()}_${esc(c.id)}_v${c.version}.txt</small></div></div><div class="source-controls"><span>Page 1 / 1 · Sample source</span>${button('Open original','original','small',`data-side="${side}" data-id="${c.id}"`)}</div><div class="paper"><h3>${esc(side==='si'?c.company:'Oceanic Shipping Co.')}</h3><div class="address">88 Industrial Road<br>Singapore 117628<br>Prepared 20 Sep 2026</div><div class="doc-title">${side==='si'?'Shipping Instructions':'Draft Bill of Lading'}</div><div class="paper-row"><span>Booking reference</span><b>${esc(c.booking)}</b></div>${FIELD_KEYS.map(k=>{const f=c.fields[k],raw=side==='si'?(f.sourceSI??f.si):(f.sourceBL??f.bl);return `<div class="paper-row ${key===k&&!full&&c.type!=='evidence'?'focus':''} ${f.comparison==='MISMATCH'?'diff':''} ${f.kind==='MISSING'?'missing':''}" data-source-field="${k}"><span>${LABELS[k]}</span><b>${esc(raw)}</b></div>`}).join('')}<p class="paper-note">Preset document for interface demonstration.<br>Review decisions do not change this source.</p></div></div>`}
function currentIssue(c,key){if(c.processingError)return c.processingError;if(c.docIssue)return c.docIssue;if(c.pairIssue)return 'pairing';const f=c.fields[key];if(f.comparison==='MATCH')return 'match';if(f.comparison==='MISMATCH')return 'mismatch';return f.reason}
const ISSUE_COPY={
 missing_value:['Missing in SI','The SI shows N/A. The BL value cannot be copied into the reference. Supply the missing information.','Upload supporting file','supplement'],
 missing_si:['SI attachment missing','A Shipping Instruction is required before these fields can be compared.','Upload SI','supplement'],
 missing_bl:['BL attachment missing','A draft Bill of Lading is required before these fields can be compared.','Upload BL','supplement'],
 wrong_type:['This file is an invoice','The attachment exists, but its content is not a draft BL. Supply the correct document.','Upload correct BL','supplement'],
 scan_illegible:['Still difficult to read','The original scan and one targeted reread did not provide a reliable value.','Upload clearer version','supplement'],
 separator_ambiguous:['Two possible numbers','22.000 MT can mean 22 or 22,000 metric tons. Choose only when the source format is known.','Choose interpretation','resolve'],
 alias_collision:['Which Portland?','The name could refer to different locations. Country or location evidence is needed.','Specify location','resolve'],
 entity_identity:['Is this the same company?','The names alone do not establish identity. Confirm only with a known business record.','Confirm with evidence','resolve'],
 extraction_incomplete:['Check the extracted value','The extracted SI count is 8, while the preset original reads 3. Correct only what the source supports.','Correct extracted value','resolve'],
 evidence_not_located:['Full document review needed','The field could not be located reliably. Both complete sample documents are shown without a location highlight.','Record manual finding','resolve'],
 port_name_code_conflict:['Name and code disagree','Singapore and MYPKG refer to different places. The source needs clarification before comparison.','Provide location evidence','resolve'],
 alias_not_found:['Reference coverage missing','Both raw names are identical, but this port is absent from the lookup table. This is not proof of a wrong port.','Provide location evidence','resolve'],
 invalid_container_count:['Container count is zero','Both documents say 0. This fails the positive-integer check; agreement alone cannot pass this record.','Request corrected information','supplement'],
 service_timeout:['Reading service timed out','No field result can be inferred from a service failure. Retry only the failed extraction stage.','Retry failed stage','retry'],
 unsupported_format:['File format not supported','A .pages attachment could not be read. Repeating the same request will not help.','Upload supported version','supplement'],
 pairing:['Choose the document pair','Several candidates exist. Select one SI and one BL belonging to this booking.','Choose SI and BL','pair'],
 mismatch:['Values differ','Both values are supported by the preset source. Verifying this issue records your review; the difference remains.','Mark difference verified','verify'],
 match:['Values agree','Both source values are equivalent under the field comparison rule. No action is needed.','View next issue','next-field']
};
function actionPanel(c,key){const issue=currentIssue(c,key),f=c.fields[key];let [title,body,label,action]=ISSUE_COPY[issue]||['Needs clarification','There is not enough evidence to compare this field.','Leave unresolved','leave'];const retryExhausted=issue==='service_timeout'&&c.retries>=1;if(retryExhausted){title='Retry limit reached';body='The one permitted retry also timed out. Keep this processing error visible and use the originals for manual review.';label='Download sample originals';action='download-originals'}if(issue==='mismatch'&&f.verified){title='Difference verified';label='View next issue';action='next-field'}return `<aside class="action-panel">${badge(issue==='match'?'Matched':issue==='mismatch'?'Difference':c.processingError?'Processing error':f.kind||'Needs action',issue==='match'?'green':issue==='mismatch'||c.processingError?'red':'amber')}<h2>${title}</h2>${!c.docIssue&&!c.processingError&&!c.pairIssue?`<div class="value-compare"><div><small>SI · Reference</small><b>${esc(f.si)}</b></div><div><small>BL · Draft</small><b>${esc(f.bl)}</b></div></div>`:''}<p>${body}</p>${issue==='alias_not_found'?'<p class="small">Raw text: identical<br>Location comparison: unresolved</p>':''}${issue==='mismatch'&&f.verified?`<div class="alert green" style="font-size:12px;margin-bottom:12px">${icon('check')}Reviewed · comparison stays different</div>`:''}${button(label,action,'primary',`data-id="${c.id}"`)}${['missing_value','missing_si','missing_bl','wrong_type','invalid_container_count'].includes(issue)?button('Copy request','copy-request','',`data-id="${c.id}"`):issue!=='match'&&!retryExhausted?button('Download sample originals','download-originals','',`data-id="${c.id}"`):''}${issue!=='match'?`<button class="leave" data-action="leave" data-id="${c.id}">Leave unresolved</button>`:''}<div class="rule" style="margin:21px 0 12px"></div><p style="font-size:11px;margin:0">SI is a comparison reference. Agreement does not prove the SI itself is correct.</p></aside>`}
function renderReview(c){if(lastReviewCase!==c.id){selectedField=FIELD_KEYS.find(k=>c.fields[k].comparison===null)||FIELD_KEYS.find(k=>c.fields[k].comparison==='MISMATCH')||'shipper';lastReviewCase=c.id}if(c.category!=='BL_COMPARISON'){go('email/'+c.id);return}if(c.pairIssue){go('pair/'+c.id);return}if(!FIELD_KEYS.includes(selectedField))selectedField=FIELD_KEYS.find(k=>c.fields[k].comparison!=='MATCH')||'shipper';const fieldButtons=FIELD_KEYS.map(k=>{const f=c.fields[k];return `<button class="field-item ${selectedField===k?'active':''}" data-action="field" data-field="${k}" aria-pressed="${selectedField===k}">${LABELS[k]}<span class="state-icon ${f.comparison==='MATCH'?'green':f.comparison==='MISMATCH'?'red':'amber'}">${c.docIssue||c.processingError?'—':f.comparison==='MATCH'?'✓':f.comparison==='MISMATCH'?'≠':'?'}</span></button>`}).join('');shell(`<section class="page review-page">${caseHeader(c)}${summary(c)}<div class="review-grid"><nav class="field-nav" aria-label="Seven fields">${fieldButtons}</nav><div><div class="evidence-pair">${sourceDoc(c,'si',selectedField)}${sourceDoc(c,'bl',selectedField)}</div><p class="evidence-caption">${c.type==='evidence'?'Source position unavailable · review the full documents.':'Both source excerpts follow the selected field.'} <span class="sample-tag">Preset evidence, not uploaded documents.</span></p></div>${actionPanel(c,selectedField)}</div></section>`,c.id+' / Field review');requestAnimationFrame(focusEvidence)}
function focusEvidence(){document.querySelectorAll('.review-grid .paper').forEach(p=>{const t=p.querySelector('.focus');if(t)p.scrollTo({top:t.offsetTop-p.offsetTop-p.clientHeight/2+t.clientHeight/2,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})})}
function renderPair(c){if(lastPairCase!==c.id){pairSelection=c.pair?{...c.pair}:{si:'',bl:''};lastPairCase=c.id}const si=pairSelection.si,bl=pairSelection.bl;const options=(side)=>{let entries=side==='si'?[['si-original','SI_'+c.id+'_v1.pdf','Original · 12 Sep · 3 pages',false],['si-revision','SI_'+c.id+'_revision.pdf','Revision · 14 Sep · 3 pages',false]]:[['bl-current','BL_'+c.id+'_draft.pdf','Current draft · 14 Sep · 2 pages',false],['bl-other','BL_BK-9902_other.pdf','Booking BK-9902 · different shipment',true]];if(c.type!=='pairing')entries=entries.slice(0,1);return entries.map(([v,name,meta,disabled])=>`<label class="file-option ${pairSelection[side]===v?'selected':''} ${disabled?'disabled':''}"><input type="radio" name="pair-${side}" value="${v}" ${pairSelection[side]===v?'checked':''} ${disabled?'disabled':''}>${icon('file')}<span>${name}<small>${meta}</small></span>${disabled?badge('Booking mismatch','red'):''}</label>`).join('')};shell(`<section class="page">${caseHeader(c,'pair')}<div class="page-head" style="margin-top:25px"><div><h1>Choose the documents for this check</h1><p>Booking ${c.booking} · select one document on each side.</p></div></div>${c.pairIssue?`<div class="alert amber" style="margin-bottom:23px">${icon('alert')}<div>Multiple versions were found. Automatic comparison is paused until you choose one SI and one BL.</div></div>`:`<div class="alert green" style="margin-bottom:23px">${icon('check')}This record already has a confirmed pair. Choosing again creates a new review version.</div>`}<div class="two-col"><div class="panel"><div class="panel-head"><h2>Shipping Instructions (SI)</h2><span class="caption">${c.type==='pairing'?'2 files':'1 file'}</span></div>${options('si')}</div><div class="panel"><div class="panel-head"><h2>Bill of Lading drafts (BL)</h2><span class="caption">${c.type==='pairing'?'2 files':'1 file'}</span></div>${options('bl')}</div></div><div class="two-col" style="margin-top:20px">${sourceDoc(c,'si','shipper',true)}${sourceDoc(c,'bl','shipper',true)}</div><div class="pair-footer"><div><p class="caption">Selection applies to this case only. Original files stay unchanged.</p><button class="link" style="margin-top:7px" data-action="multiple" data-id="${c.id}">These are multiple shipments</button></div><div class="flex">${button('Leave unresolved','leave','ghost',`data-id="${c.id}"`)}${button('Continue with selected pair '+icon('arrow'),'confirm-pair','primary',`data-id="${c.id}" ${!si||!bl?'disabled':''}`)}</div></div></section>`,c.id+' / Pair documents')}
function renderEmail(c){const body=c.body||`Hi team,\n\nPlease compare the attached draft BL against the SI for booking ${c.booking}. Please check the shipment details and highlight any differences before we proceed.\n\nThank you,\n${c.company}`;const hit=/\b(SI|BL)\b|B\/L|shipping instructions?|bills? of lading/i.test(body);shell(`<section class="page">${caseHeader(c,'email')}<div class="split-uneven" style="margin-top:25px"><div class="panel"><div class="panel-head"><h2>${c.category==='BL_COMPARISON'?'Please check the attached draft BL':category(c)}</h2>${icon('mail')}</div><div class="panel-body"><div class="mini-rows"><div><span class="muted">From</span><span>${esc(c.company)}</span></div><div><span class="muted">Received</span><span>20 Sep 2026, 10:14</span></div><div><span class="muted">Record</span><span>${c.id}</span></div></div><div class="email-body">${esc(body)}</div><div class="rule"></div><p class="caption" style="margin-top:15px">${c.category==='BL_COMPARISON'?'Attachments: preset SI and draft BL candidates':'Attachments are not compared for this category.'}</p></div></div><aside class="stack"><div class="panel"><div class="panel-head"><h2>Classification</h2></div><div class="panel-body">${badge(category(c),c.category==='BL_COMPARISON'?'red':'')}<div class="mini-rows" style="margin-top:16px"><div><span>Keyword entry</span><span>${hit?'Keyword found':'No keyword hit'}</span></div><div><span>Reading coverage</span><span>Full subject + body</span></div></div><p class="scope-note" style="font-size:14px">${c.category==='BL_COMPARISON'?'The current email explicitly requests a comparison of the draft BL with the SI.':c.category==='SI_REQUEST'?'The sender requests preparation of an SI, not a comparison against a BL.':'The message does not request an SI–BL comparison in this preset scenario.'}</p>${!hit?'<div class="alert amber">No keyword hit means this version skips the comparison route. It does not prove that a check is unnecessary.</div>':''}</div></div><div class="alert ${c.category==='BL_COMPARISON'?'':'green'}">${icon('check')}<div>${c.category==='BL_COMPARISON'?'Continue to the document and field review.':'Classification complete. Seven-field checking is not applicable.'}</div></div><a class="btn ${c.category==='BL_COMPARISON'?'primary':''}" href="#${c.category==='BL_COMPARISON'?(c.pairIssue?'pair/':'review/')+c.id:'inbox'}">${c.category==='BL_COMPARISON'?'Open document review':'Back to inbox'}${icon('arrow')}</a></aside></div></section>`,c.id+' / Email')}
function renderHistory(c){shell(`<section class="page">${caseHeader(c,'history')}<div class="page-head" style="margin-top:30px"><div><h2>Review history</h2><p>Source versions, decisions and unresolved issues stay visible.</p></div>${badge('Current version '+c.version)}</div>${c.sourceVersions?.length?button('View previous source versions','source-versions','',`data-id="${c.id}"`):''}<div class="history-list">${c.history.map(h=>`<div class="history-item"><strong>${esc(h.title)}</strong><p>${esc(h.detail)}</p><small>${esc(h.at)} · Preset workspace</small></div>`).join('')}</div><div class="alert">${icon('file')}Reviewing a difference does not change its comparison result. Corrections create a new extraction version.</div></section>`,c.id+' / History')}
function renderImport(){shell(`<section class="page"><div class="page-head"><div><h1>Import materials</h1><p>Add email records and their attachments to prepare a batch.</p></div>${badge('Preset demo')}</div><div class="split-uneven"><div class="stack"><div class="panel" style="padding:17px"><div class="dropzone" id="dropzone"><div class="drop-icon">${icon('file')}</div><h2>Drop email JSON and attachments here</h2><p>Files are staged locally. This prototype does not run OCR.</p><input type="file" id="import-files" multiple accept=".json,.zip,.pdf,.png,.jpg,.jpeg,.tif,.tiff,.txt,.docx,.xlsx" hidden>${button(icon('upload')+'Choose files','choose-import','primary')}<p style="font-size:12px;margin:16px 0 0">JSON, ZIP, PDF, images and text documents</p></div></div><div class="panel"><div class="panel-head"><h2>Staged files</h2>${staged.length?button('Clear all','clear-import','ghost small'):badge('0')}</div><div class="panel-body">${staged.length?staged.map(f=>`<div class="file-staged">${icon('file')}<span class="filename">${esc(f.name)}<small class="muted" style="display:block">${f.info||Math.ceil(f.size/1024)+' KB'}</small></span>${badge(f.error?'Check file':'Staged',f.error?'amber':'green')}</div>`).join(''):'<p class="caption" style="padding:20px 0">No files selected yet.</p>'}${importErrors.map(x=>`<div class="alert amber" style="margin-top:12px">${icon('alert')}${esc(x)}</div>`).join('')}</div></div></div><aside class="stack"><div class="panel"><div class="panel-head"><h2>Before processing</h2></div><div class="panel-body"><ul class="steps">${[['Email body available','JSON records include a subject and full body.'],['Attachments linked to records','Keep each file associated with its email.'],['Originals retained','Evidence stays available throughout review.']].map(([a,b],i)=>`<li><span class="step-number ${demoStaged?'done':''}">${demoStaged?'✓':i+1}</span><div>${a}<small>${b}</small></div></li>`).join('')}</ul></div></div><div class="panel"><div class="panel-head"><h2>Explore with sample materials</h2></div><div class="panel-body"><p class="caption">Load the preset batch to try every review path. No files are sent to a server.</p>${button('Load example batch','load-demo','', 'style="margin-top:16px;width:100%"')}<ul class="steps"><li><span class="step-number">1</span><div>Classify emails<small>Keyword entry, then full-message intent.</small></div></li><li><span class="step-number">2</span><div>Extract and validate<small>Check values before comparison.</small></div></li><li><span class="step-number">3</span><div>Review the exceptions<small>Keep differences and unknowns visible.</small></div></li></ul>${button(icon('arrow')+'Run sample batch','start-demo','primary block',!demoStaged?'disabled':'')}<p class="footer-note">This runs a simulated progress sequence over preset cases.</p></div></div></aside></div></section>`,'Import materials','import');const z=document.getElementById('dropzone');z.addEventListener('dragover',e=>{e.preventDefault();z.classList.add('over')});z.addEventListener('dragleave',()=>z.classList.remove('over'));z.addEventListener('drop',e=>{e.preventDefault();stageFiles(e.dataTransfer.files)})}
async function stageFiles(files){demoStaged=false;importErrors=[];staged=[];for(const file of files){const ext=file.name.split('.').pop().toLowerCase(),entry={name:file.name,size:file.size};if(!['json','zip','pdf','png','jpg','jpeg','tif','tiff','txt','docx','xlsx'].includes(ext)){entry.error=true;importErrors.push(file.name+': unsupported format.')}if(ext==='json'){try{const data=JSON.parse(await file.text());const items=Array.isArray(data)?data:Array.isArray(data.emails)?data.emails:data.email_id?[data]:null;if(!items){entry.error=true;importErrors.push('Email JSON should contain records with email_id, subject and body.')}else{const bad=items.filter(x=>!x.email_id||typeof x.subject!=='string'||typeof x.body!=='string');entry.info=items.length+' email records';if(bad.length){entry.error=true;importErrors.push(bad.length+' records are missing email_id, subject or body.')}}}catch{entry.error=true;importErrors.push(file.name+': invalid JSON.')}}staged.push(entry)}if(!staged.some(f=>f.name.toLowerCase().endsWith('.json')))importErrors.push('Add an email JSON file to define the batch.');importErrors.push('Uploaded materials are previewed locally only. Use the example batch to explore processing.');renderImport()}
function renderProgress(){const p=progress||0;const stages=['Read email records','Identify SI and BL candidates','Extract and validate fields','Compare and prepare review'];shell(`<section class="page"><div class="page-head"><div><h1>${p>=100?'Sample batch is ready':'Preparing your sample batch'}</h1><p>Demonstration sequence · no OCR or AI requests are being made.</p></div>${badge(p>=100?'Complete':'Simulation',p>=100?'green':'')}</div><div class="split-uneven"><div class="panel"><div class="panel-head"><h2>Batch EX-DEMO-01</h2><strong>${p}%</strong></div><div class="panel-body"><div class="progressbar" role="progressbar" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100"><span style="width:${p}%"></span></div><ul class="steps">${stages.map((s,i)=>`<li><span class="step-number ${p>=(i+1)*25?'done':p>=i*25?'current':''}">${p>=(i+1)*25?'✓':i+1}</span><div>${s}<small>${p>=(i+1)*25?'Sample stage complete':p>=i*25?'Showing this stage':'Queued'}</small></div></li>`).join('')}</ul>${p>=100?`<a href="#inbox" class="btn primary">Open work queue ${icon('arrow')}</a>`:button('Run / resume sample sequence','resume-progress','primary')}</div></div><div class="stack"><div class="alert amber">${icon('alert')}<div>Exceptions remain visible<small>Missing values, ambiguous pairing and processing failures follow different recovery paths.</small></div></div><div class="panel"><div class="panel-body"><h3>Only suspicious fields are reread</h3><p class="scope-note">Extraction → rule checks → targeted reread when useful → recheck. Missing facts are never filled in by repetition.</p></div></div><a class="btn" href="#inbox">Return to inbox</a></div></div></section>`,'Processing','import')}
function runProgress(){clearInterval(progressTimer);if(progress>=100)progress=0;go('progress');progressTimer=setInterval(()=>{progress=Math.min(100,progress+10);if(route()[0]==='progress')renderProgress();if(progress===100){clearInterval(progressTimer);const c=getCase('BK-2213');if(c?.processing){c.processing=false;recheckPreset(c);addHistory(c,'Sample processing completed','Preset values passed the seven comparison rules.')}toast('Sample batch ready. Exceptions remain in the work queue.')}},450)}
function exportBlock(c){if(c.category!=='BL_COMPARISON')return 'Non-comparison placeholder needs mapping';if(c.processing)return 'Processing not complete';if(c.processingError)return 'Execution failure is not an official review reason';if(c.pairIssue)return 'Pairing / multi-case mapping not confirmed';const n=counts(c);if(n.diff&&n.unresolved)return 'Mixed-result priority not confirmed';if(n.unresolved&&Object.values(c.fields).some(f=>f.kind==='AMBIGUOUS'))return 'Internal reason has no confirmed official mapping';return null}
function internalReport(){return {report_type:'PRESET_DEMO_NOT_A_COMPETITION_SUBMISSION',generated_at:new Date().toISOString(),cases:cases.map(c=>({email_id:c.id,category:c.category,source_versions:c.sourceVersions||[],comparison_scope:c.category==='BL_COMPARISON'?'SI versus BL':'not_applicable',review_progress:mode(c),finding:finding(c),fields:c.category==='BL_COMPARISON'?c.fields:null,processing_error:c.processingError||null,document_issue:c.docIssue||null,pairing_issue:!!c.pairIssue,export_block:exportBlock(c),version:c.version,history:c.history}))}}
function renderExports(){const list=cases;const all=cases.length,checks=cases.filter(c=>c.category==='BL_COMPARISON').length,diffs=cases.filter(c=>c.category==='BL_COMPARISON'&&counts(c).diff>0).length,unresolved=cases.filter(c=>c.category==='BL_COMPARISON'&&!c.processingError&&!c.processing&&(c.docIssue||c.pairIssue||counts(c).unresolved)).length,errors=cases.filter(c=>c.processingError).length;const c=getCase(selected)||cases[0],blocked=cases.filter(c=>exportBlock(c));shell(`<section class="page"><div class="page-head"><div><h1>Results & export</h1><p>Known differences and unresolved issues stay in the report.</p></div><span class="caption">Batch EX-DEMO-01</span></div><div class="metrics">${[[all,'emails','mail',''],[checks,'BL checks','file',''],[diffs,'with differences','alert','red'],[unresolved,'unresolved','alert','amber'],[errors,'processing errors','alert','red']].map(([n,t,i,col])=>`<div class="metric ${col}">${icon(i)}<span><b>${n}</b>${t}</span></div>`).join('')}</div><div class="export-layout"><div><div class="panel"><div class="panel-head"><h2>Batch results</h2>${badge('Preset records')}</div><div class="table-wrap"><table class="case-table"><thead><tr><th>Email ID</th><th>Category</th><th>Finding</th><th>Export check</th><th></th></tr></thead><tbody>${rows(list,true)}</tbody></table></div><div class="table-footer"><span>${all} example emails retained</span><span>Counts can overlap</span></div></div></div><aside class="stack"><div class="panel"><div class="panel-head"><h2>${c.id}</h2>${icon('file')}</div><div class="panel-body"><p class="caption">${esc(c.company)}</p><div class="alert ${color(c)}" style="margin:17px 0">${icon('alert')}<div>${esc(finding(c))}</div></div><p class="caption">${exportBlock(c)||'This simple preset case has a known result shape. It is still example data.'}</p><a class="link" style="display:block;margin-top:15px" href="#${c.category==='BL_COMPARISON'?'review':'email'}/${c.id}">Open evidence & details</a></div></div><div class="panel"><div class="panel-head"><h2>Download</h2></div><div class="panel-body">${button(icon('download')+'Internal review report','download-report','primary block')}${button('Preview JSON','preview-json','block','style="margin-top:8px"')}<p class="footer-note">Includes all ${all} preset records, known differences, source values and review history.</p></div></div><div class="alert amber">${icon('alert')}<div><strong>Competition export unavailable</strong><small>This is a preset prototype, not a scored dataset run. ${blocked.length} records also have unresolved export mappings.</small><button class="link" style="margin-top:10px;color:inherit" data-action="export-blocks">View export checks</button></div></div></aside></div></section>`,'Results & export','exports')}
function renderGuide(){const groups=[['Start & manage',[['inbox','Inbox','Tasks, filters and a linked detail panel'],['import','Import materials','Local staging, validation and sample batch'],['progress','Processing','Named stages and a bounded demo sequence'],['completed','Completed','Matches, verified differences and classifications'],['exports','Results & export','All findings and honest export readiness']]],['Source & pairing',[['email/BK-2048','Email & classification','Full body, category and keyword evidence'],['pair/SI-7781','Multiple versions','Choose exactly one SI and one BL'],['review/SI-4021','Missing BL','Upload the missing document'],['review/SI-4022','Missing SI','Keep the reference source missing'],['review/BK-2209','Wrong document type','Invoice does not substitute for a BL'],['review/BK-2208','Evidence unavailable','Full human review, without false localization']]],['Field review',[['review/BL-7720','All seven fields match','No unresolved issue; reference boundary remains'],['review/BK-2048','Difference + missing value','Both findings visible at the same time'],['review/BK-2205','Confirmed difference','Review progress changes; difference remains'],['review/BL-3312','Unreadable scan','Clearer version after the reread limit'],['review/BK-2204','Extraction correction','Correct one value with source evidence'],['history/BK-2048','Review history','Versions, sources and decisions']]],['Interpretation & identity',[['review/BK-2201','Number ambiguity','Choose only with number-format evidence'],['review/BK-2202','Port alias collision','Location choices require supporting facts'],['review/BK-2210','Port name / code conflict','Clarify the contradiction in the source'],['review/BK-2211','Unknown port alias','Equal raw text is not a verified location'],['review/BK-2203','Company identity','Same or different, with evidence'],['review/BK-2212','Invalid value','Equal zero counts still fail validity checks']]],['Failures & classification',[['review/SI-0092','Temporary service failure','Retry the failed stage once, then stop'],['review/BK-2207','Unsupported format','Supply a readable file; no blind retry'],['email/MAIL-1190','SI request','Classification only'],['email/MAIL-1191','Invoice query','No seven-field pass'],['email/MAIL-1192','General email','No keyword hit remains inspectable'],['email/MAIL-1193','Spam','Retained in the full batch output']]]];shell(`<section class="page"><div class="page-head"><div><h1>Every page. Every next step.</h1><p>A page guide for reviewing the complete Verity prototype.</p></div>${badge('23 preset cases')}</div><div class="alert" style="margin-bottom:28px">${icon('layers')}<div>Shared review layout, different actions<small>Each example uses the same field list and two source documents. The action panel changes with the actual issue.</small></div></div><div class="guide-groups">${groups.map(([title,links])=>`<section class="guide-group"><h2>${title}</h2>${links.map(([url,t,d])=>`<a class="guide-link" href="#${url}" data-action="guide-link" data-id="${url.split('/')[1]||''}"><span>${t}<small>${d}</small></span>${icon('arrow')}</a>`).join('')}</section>`).join('')}</div><p class="scope-note">White surfaces, coral actions, soft pink selection, green agreement and amber uncertainty. The original files stay unchanged. Leaving an issue unresolved is always allowed.</p><p class="footer-note">Interactive design prototype · predefined text and local decisions · no live inbox, OCR, AI service or external messages.</p></section>`,'Page guide','screens')}
function openModal(title,body,actions=''){const d=document.getElementById('modal');d.innerHTML=`<div class="flex between"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}${actions?`<div class="modal-actions">${button('Cancel','close-modal')}${actions}</div>`:''}`;d.showModal()}
function closeModal(){document.getElementById('modal').close()}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function resolveModal(c){const issue=currentIssue(c,selectedField);let choices='';const choice=(value,label,sub)=>`<label class="option-choice"><input type="radio" name="resolution" value="${value}"><span>${label}<small>${sub}</small></span></label>`;if(issue==='separator_ambiguous')choices=choice('22000','22 metric tons → 22,000 kg','Dot is the decimal separator; equals the BL value.')+choice('22000000','22,000 metric tons → 22,000,000 kg','Dot is the thousands separator; differs from the BL.');else if(issue==='alias_collision')choices=choice('USPDX','Portland, Oregon · USPDX','United States · matches the BL location.')+choice('AUPTJ','Portland, Victoria · AUPTJ','Australia · differs from the BL location.');else if(issue==='entity_identity')choices=choice('same','Same entity','A known business identifier or verified alias supports this.')+choice('different','Different entities','Business evidence establishes distinct entities.');else if(issue==='extraction_incomplete')choices='<label class="field-label" for="correction">Correct container count from the source</label><input id="correction" type="number" min="1" step="1" placeholder="Enter the value shown in the SI" class="full-width">';else if(issue==='evidence_not_located')choices='<label class="field-label" for="manual-si">SI notify party, transcribed from the original</label><input id="manual-si" class="full-width" placeholder="Enter the complete source value">';else choices='<label class="field-label" for="location-code">Confirmed SI location code</label><input id="location-code" class="full-width" placeholder="Example: SGSIN"><p style="font-size:12px;margin-top:7px">Provide a verified code and explain the supporting document. No fuzzy matching is used.</p>';openModal(ISSUE_COPY[issue][0],`<p>${ISSUE_COPY[issue][1]}</p>${choices}${issue==='alias_not_found'?'<label class="field-label" for="bl-location-code">Confirmed BL location code</label><input id="bl-location-code" class="full-width" placeholder="Confirm the BL location independently">':''}<label class="field-label" for="evidence-note">Evidence / source reference <span class="red">*</span></label><textarea id="evidence-note" placeholder="Document, page and the fact supporting this decision"></textarea><p style="font-size:12px;margin-top:10px">Applies to this case only. It does not create a global alias or change the original document.</p><p id="form-error" class="red" role="alert"></p>`,button('Save decision & recheck','save-resolution','primary',`data-id="${c.id}" data-issue="${issue}"`))}
function applyResolution(c,issue){const note=document.getElementById('evidence-note').value.trim(),selectedValue=document.querySelector('input[name="resolution"]:checked')?.value,f=c.fields[selectedField];const fail=t=>{document.getElementById('form-error').textContent=t;return false};if(note.length<8)return fail('Add a specific source reference and supporting fact.');let si=f.si,comp=null;if(['separator_ambiguous','alias_collision','entity_identity'].includes(issue)&&!selectedValue)return fail('Choose an interpretation, or leave the issue unresolved.');if(issue==='separator_ambiguous'){si=selectedValue==='22000'?'22,000 kg':'22,000,000 kg';comp=selectedValue==='22000'?'MATCH':'MISMATCH';f.normalizedSI=Number(selectedValue)}else if(issue==='alias_collision'){si='Portland ('+selectedValue+')';comp=selectedValue==='USPDX'?'MATCH':'MISMATCH';f.normalizedSI=selectedValue}else if(issue==='entity_identity'){comp=selectedValue==='same'?'MATCH':'MISMATCH';f.identityDecision=selectedValue}else if(issue==='extraction_incomplete'){const n=Number(document.getElementById('correction').value);if(!Number.isSafeInteger(n)||n<1)return fail('Enter a positive whole container count.');if(n!==Number(f.sourceSI))return fail('The preset source shows 3. Enter the source value rather than a desired result.');si=String(n);comp=n===Number(f.bl)?'MATCH':'MISMATCH'}else if(issue==='evidence_not_located'){si=document.getElementById('manual-si').value.trim();if(!si)return fail('Transcribe the SI value first.');comp=si.toLowerCase()===f.bl.toLowerCase()?'MATCH':'MISMATCH'}else{const code=document.getElementById('location-code').value.trim().toUpperCase();if(!/^[A-Z]{5}$/.test(code))return fail('Enter a five-letter location code with supporting evidence.');if(!['SGSIN','MYPKG','USLAX','USPDX','AUPTJ'].includes(code))return fail('This preset only verifies SGSIN, MYPKG, USLAX, USPDX and AUPTJ. Other codes remain unresolved.');if(issue==='alias_not_found'){const blCode=document.getElementById('bl-location-code').value.trim().toUpperCase();if(!['SGSIN','MYPKG','USLAX','USPDX','AUPTJ'].includes(blCode))return fail('Provide a supported, independently verified BL code as well.');f.normalizedBL=blCode;comp=code===blCode?'MATCH':'MISMATCH'}else comp=code==='SGSIN'?'MATCH':'MISMATCH';si=code;f.normalizedSI=code}if(!f.sourceSI)f.sourceSI=f.si;const before=f.si;f.si=si;f.comparison=comp;f.kind=null;f.reason=null;f.evidenceNote=note;f.verified=false;c.version++;addHistory(c,'Field decision saved',LABELS[selectedField]+': '+before+' → '+si+'. '+comp+'. Evidence: '+note);closeModal();render();toast('Decision saved. Affected field rechecked; original unchanged.')}
function supplementModal(c){const issue=currentIssue(c,selectedField),sampleSupported=['missing_value','scan_illegible','missing_si','missing_bl','wrong_type','unsupported_format','invalid_container_count'].includes(issue);openModal('Add supporting material',`<p>${ISSUE_COPY[issue]?.[1]||'Add source evidence to support the review.'}</p><label class="field-label" for="support-file">Choose a local file</label><input id="support-file" type="file" accept=".pdf,.png,.jpg,.jpeg,.txt,.docx,.xlsx"><p style="font-size:12px;margin-top:10px">Your file is staged on this device. Live extraction is not connected, so an upload alone will not mark this issue resolved.</p><div class="rule" style="margin:20px 0"></div>${sampleSupported?`<h3>Try the preset recovery</h3><p style="margin-top:7px">Use an explicitly simulated ${issue==='scan_illegible'?'clearer scan':issue==='missing_value'?'SI supplement with gross weight 235,550 KG':issue==='invalid_container_count'?'corrected SI count of 3':'replacement document'} to see the next state.</p>`:''}`,button('Stage selected file','stage-support','',`data-id="${c.id}"`)+(sampleSupported?button('Use example & recheck','sample-support','primary',`data-id="${c.id}" data-issue="${issue}"`):''))}
function recheckPreset(c){for(const f of Object.values(c.fields)){if(f.reason==='comparison_paused'){f.comparison=f.si===f.bl?'MATCH':'MISMATCH';f.reason=null;f.kind=null}}}
function supplementExample(c,issue){const oldSource=Object.fromEntries(FIELD_KEYS.map(k=>[k,{si:c.fields[k].sourceSI??c.fields[k].si,bl:c.fields[k].sourceBL??c.fields[k].bl}]));c.sourceVersions=c.sourceVersions||[];c.sourceVersions.push({version:c.version,fields:oldSource});if(c.docIssue){c.docIssue=null;recheckPreset(c);c.version++;addHistory(c,'Example source supplied','A preset '+(issue==='missing_si'?'SI':'BL')+' was explicitly selected. Seven preset fields were rechecked.')}else if(c.processingError==='unsupported_format'){c.processingError=null;recheckPreset(c);c.version++;addHistory(c,'Example readable file supplied','A preset text document replaced the unsupported example format.')}else{const f=c.fields[selectedField];if(!f.sourceSI)f.sourceSI=f.si;const newValue=issue==='invalid_container_count'?'3':'235,550 KG';f.si=newValue;f.sourceSI=newValue;f.kind=null;f.reason=null;f.comparison=newValue===f.bl?'MATCH':'MISMATCH';f.verified=false;c.version++;addHistory(c,'Example supplement applied',LABELS[selectedField]+': new preset source value '+newValue+'. Comparison '+f.comparison+'. Old source version retained in history.')}closeModal();render();toast('Example material applied and rechecked.')}
function handleAction(a,b){if(a==='nav-inbox'){filter='needs';search='';issueFilter='all';go('inbox');return}const c=getCase(b.dataset.id||route()[1]||selected);if(a==='field'){selectedField=b.dataset.field;render();focusEvidence()}else if(a==='guide-link'){const x=getCase(b.dataset.id);if(x)selectedField=FIELD_KEYS.find(k=>x.fields[k].comparison!=='MATCH')||'shipper'}else if(a==='close-modal')closeModal();else if(a==='original'){openModal('Original '+b.dataset.side.toUpperCase()+' · preset source',`<p>Complete sample source. This is a generated fixture, not a processed upload.</p><pre>${esc(originalText(c,b.dataset.side))}</pre>`,button('Download sample source','download-source','primary',`data-id="${c.id}" data-side="${b.dataset.side}"`))}else if(a==='source-versions')openModal('Previous source versions',`<p>Source snapshots retained before example replacements.</p><pre>${esc(JSON.stringify(c.sourceVersions,null,2))}</pre>`);else if(a==='download-source'){download(`${c.id}_${b.dataset.side.toUpperCase()}_sample.txt`,originalText(c,b.dataset.side),'text/plain')}else if(a==='download-originals'){download(c.id+'_sample_originals.txt',originalText(c,'si')+'\n\n'+originalText(c,'bl'),'text/plain');toast('Sample originals downloaded.')}else if(a==='leave'){addHistory(c,'Left unresolved','No unsupported conclusion was added. Current findings remain.');go('inbox');toast('Case remains in the work queue.')}else if(a==='verify'){const f=c.fields[selectedField];if(f.comparison!=='MISMATCH')return;f.verified=true;addHistory(c,'Difference verified',LABELS[selectedField]+': SI '+f.si+' / BL '+f.bl+'. Comparison remains MISMATCH.');render();toast('Review saved. The difference is still recorded.')}else if(a==='next-field'){const k=FIELD_KEYS.find(k=>c.fields[k].comparison===null||c.fields[k].comparison==='MISMATCH'&&!c.fields[k].verified);if(k){selectedField=k;render()}else{go('completed');toast('No unresolved field review remains.')}}else if(a==='resolve')resolveModal(c);else if(a==='save-resolution')applyResolution(c,b.dataset.issue);else if(a==='supplement')supplementModal(c);else if(a==='sample-support')supplementExample(c,b.dataset.issue);else if(a==='stage-support'){const f=document.getElementById('support-file').files[0];if(!f){toast('Choose a supporting file first.');return}addHistory(c,'Local material staged',f.name+' · live extraction unavailable; the issue remains unresolved.');closeModal();render();toast('File staged. Result remains unresolved until extraction is connected.')}else if(a==='copy-request'){const text=`Please provide ${c.docIssue==='missing_si'?'the missing SI':c.docIssue?'the correct draft BL':LABELS[selectedField]+' in the SI'} for booking ${c.booking}. We cannot complete the comparison without source evidence.`;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>toast('Request copied. Nothing was sent.')).catch(()=>openModal('Request text',`<textarea readonly>${esc(text)}</textarea>`));else openModal('Request text',`<textarea readonly>${esc(text)}</textarea>`)}else if(a==='retry'){if(c.retries>=1)return;c.retries=1;addHistory(c,'Failed extraction stage retried','Preset retry returned the same service timeout. Retry budget is exhausted; no field values were changed.');render();toast('Preset retry failed. Retry limit reached.')}else if(a==='pair')go('pair/'+c.id);else if(a==='confirm-pair'){if(!pairSelection.si||pairSelection.bl!=='bl-current')return;c.pairIssue=false;recheckPreset(c);c.version++;c.pair={...pairSelection};addHistory(c,'Document pair selected',pairSelection.si+' + '+pairSelection.bl+'. Preset comparison completed. Selection applies to this case only.');selectedField='shipper';go('review/'+c.id);toast('Pair selected and preset fields compared.')}else if(a==='multiple'){c.multiple=true;addHistory(c,'Multiple shipments flagged','Operator kept the case unresolved pending organization. No shipment was chosen for export.');go('inbox');toast('Marked for shipment organization.')}else if(a==='choose-import')document.getElementById('import-files').click();else if(a==='clear-import'){staged=[];demoStaged=false;importErrors=[];render()}else if(a==='load-demo'){staged=[{name:'sample_emails.json',info:cases.length+' preset email records'},{name:'sample_attachments.zip',info:'Generated sample SI and BL sources'}];demoStaged=true;importErrors=[];render()}else if(a==='start-demo'||a==='resume-progress')runProgress();else if(a==='download-report'){download('verity_demo_review_report.json',JSON.stringify(internalReport(),null,2));toast('Internal demo report downloaded — not a competition submission.')}else if(a==='preview-json')openModal('Internal report preview',`<p>All preset records are included. This file is not a scored competition submission.</p><pre>${esc(JSON.stringify(internalReport().cases.find(x=>x.email_id===selected)||internalReport().cases[0],null,2))}</pre>`,button('Download full report','download-report','primary'));else if(a==='export-blocks')openModal('Competition export checks',`<p>Preset data cannot be submitted as real evaluation results. The technical reference also requires explicit mapping for these cases:</p><div class="mini-rows">${cases.filter(x=>exportBlock(x)).map(x=>`<div><strong>${x.id}</strong><span>${esc(exportBlock(x))}</span></div>`).join('')}</div><p style="margin-top:15px">The internal report remains available and retains every known finding.</p>`)}
function originalText(c,side){return `PRESET SAMPLE — NOT A LIVE SHIPMENT DOCUMENT\n${side==='si'?'SHIPPING INSTRUCTIONS':'DRAFT BILL OF LADING'}\nBooking: ${c.booking}\n\n`+FIELD_KEYS.map(k=>`${LABELS[k]}: ${side==='si'?(c.fields[k].sourceSI??c.fields[k].si):(c.fields[k].sourceBL??c.fields[k].bl)}`).join('\n')}
function handleChange(e){if(e.target.name?.startsWith('pair-')){pairSelection[e.target.name.slice(5)]=e.target.value;render()}else if(e.target.id==='import-files')stageFiles(e.target.files)}
document.getElementById('modal').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal()});
try{const ctx=document.modelContext;if(ctx?.registerTool){ctx.registerTool({name:'list_review_cases',description:'Read the preset cases and their current review states.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>cases.map(c=>({id:c.id,finding:finding(c),progress:mode(c)}))});ctx.registerTool({name:'open_review_case',description:'Navigate to a preset case without changing its findings.',inputSchema:{type:'object',properties:{case_id:{type:'string'}},required:['case_id'],additionalProperties:false},execute:async input=>{const c=getCase(input?.case_id);if(!c)throw new Error('Unknown preset case');selectedField=FIELD_KEYS.find(k=>c.fields[k].comparison!=='MATCH')||'shipper';go((c.category==='BL_COMPARISON'?'review/':'email/')+c.id);await new Promise(r=>requestAnimationFrame(r));return {id:c.id,finding:finding(c)}}})}}catch{}
render();
